# Merge the person into another (a steward only): their claims, names, patrons and pool memberships move to the other.
validate:
  class: net.officefloor.hq.app.person.ValidateMerge
  next: snapshot
# The sheet's figures before the change, so the change can audit what it moved.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: merge
merge:
  class: net.officefloor.hq.app.person.MergePerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
# Retire the person from a date: no claim of theirs may be dated after it.
validate:
  class: net.officefloor.hq.app.person.ValidateRetire
  next: snapshot
# The sheet's figures before the change, so the change can audit what it moved.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidateMerge {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody MergeRequest request, Out<MergeRequest> body, Settings settings)
            throws InvalidPersonException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        if (request.intoId() == null || request.intoId().isBlank()) {
            throw new InvalidPersonException("No person chosen to merge into");
        }
        body.set(request);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Val;

/**
 * Merges the person into another (a steward only; never into themselves, nor when either is retired). Their claims
 * move to the other, numbers and dates kept, listed after the other's in the order they were added, each unbound
 * from any statement; their name and aliases become the other's aliases; their patrons are added to the other's
 * and whoever named them as patron names the other instead (never themselves, never twice); their pool memberships
 * move to the other (shares added where the other is already a member). Their statements, holds, watchers and
 * contact are dropped and they leave the sheet.
 */
public class MergePerson {
    public void merge(@Val MergeRequest request, @Val Person person, People people, Claims claims, Settings settings,
            Audit audit, @Val RollupFigures before, Rollup rollup) throws InvalidPersonException {
        String sheetId = person.getSheetId();
        if (!Settings.STEWARD.equals(settings.role(sheetId, request.user()))) {
            throw new InvalidPersonException("Only a steward can merge people");
        }
        Person into = null;
        try {
            into = people.find(sheetId, Long.parseLong(request.intoId().trim()));
        } catch (NumberFormatException e) {
            // not an id this app assigned
        }
        if (into == null) {
            throw new InvalidPersonException("The person to merge into is not on the sheet");
        }
        if (into.getId() == person.getId()) {
            throw new InvalidPersonException("A person cannot be merged into themselves");
        }
        if (person.getRetiredFrom() != null || into.getRetiredFrom() != null) {
            throw new InvalidPersonException("A retired person cannot be merged");
        }
        java.util.List<Claim> moved = new java.util.ArrayList<>(claims.ofPerson(sheetId, person.getId()));
        moved.sort(java.util.Comparator.comparingLong(Claim::getId));
        for (Claim claim : moved) {
            claims.merge(claim, into.getId());
        }
        people.merge(person, into);
        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + request.user()
                + " from=" + person.getName() + " into=" + into.getName());
        rollup.recordChanges(sheetId, request.user(), before);
    }
}
package net.officefloor.hq.app.person;

/** Body of POST /api/sheets/{sheetId}/people/{personId}/merge: the id of the person merged into, and who merges. */
public record MergeRequest(String intoId, String user) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidateRetire {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody RetireRequest request, Out<ValidRetire> body, Settings settings)
            throws InvalidPersonException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String raw = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!raw.isEmpty()) {
            try {
                date = LocalDate.parse(raw);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The retirement date is not a date");
            }
        }
        body.set(new ValidRetire(date, request.user()));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.sheet.Sheets;
