170	    /** Merges the person into another (their claims already moved): their name and aliases become the other's
171	     *  aliases; their patrons are added to the other's and whoever named them names the other instead (never
172	     *  themselves, never twice); their pool memberships move to the other, shares added where the other is already
173	     *  a member; their fixed period figures add to the other's. Their statements, holds, watchers and contact go
174	     *  with them as they leave the sheet. */
175	    public void merge(Person from, Person into) {
176	        String sheetId = from.getSheetId();
177	        long fromId = from.getId();
178	        long intoId = into.getId();
179	        // Names.
180	        java.util.List<String> names = new java.util.ArrayList<>();
181	        names.add(from.getName());
182	        names.addAll(jdbc.queryForList("SELECT alias FROM person_alias WHERE sheet_id = ? AND person_id = ? ORDER BY seq",
183	                String.class, sheetId, fromId));
184	        jdbc.update("DELETE FROM person_alias WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
185	        for (String name : names) {
186	            addAlias(into, name);
187	        }
188	        // Patrons the merged person named.
189	        for (Long patron : from.getPatronIds()) {
190	            if (patron != intoId && !into.getPatronIds().contains(patron)) {
191	                jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, set_on) VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
192	                        sheetId, intoId, patron, sheetId);
193	                into.getPatronIds().add(patron);
194	            }
195	        }
196	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
197	        // Whoever named the merged person names the other instead.
198	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND patron_id = ? AND (person_id = ? OR person_id IN"
199	                + " (SELECT person_id FROM person_patron WHERE sheet_id = ? AND patron_id = ?))",
200	                sheetId, fromId, intoId, sheetId, intoId);
201	        jdbc.update("UPDATE person_patron SET patron_id = ? WHERE sheet_id = ? AND patron_id = ?", intoId, sheetId, fromId);
202	        // Pool memberships.
203	        jdbc.update("UPDATE pool_member m SET share = share + (SELECT f.share FROM pool_member f WHERE f.sheet_id = m.sheet_id"
204	                + " AND f.pool_name = m.pool_name AND f.person_id = ?) WHERE m.sheet_id = ? AND m.person_id = ? AND EXISTS"
205	                + " (SELECT 1 FROM pool_member f WHERE f.sheet_id = m.sheet_id AND f.pool_name = m.pool_name AND f.person_id = ?)",
206	                fromId, sheetId, intoId, fromId);
207	        jdbc.update("DELETE FROM pool_member WHERE sheet_id = ? AND person_id = ? AND pool_name IN"
208	                + " (SELECT pool_name FROM pool_member WHERE sheet_id = ? AND person_id = ?)", sheetId, fromId, sheetId, intoId);
209	        jdbc.update("UPDATE pool_member SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);
210	        // Fixed period figures.
211	        jdbc.update("UPDATE period_person_total t SET total = total + (SELECT f.total FROM period_person_total f WHERE f.sheet_id = t.sheet_id"
212	                + " AND f.period_name = t.period_name AND f.person_id = ?) WHERE t.sheet_id = ? AND t.person_id = ? AND EXISTS"
213	                + " (SELECT 1 FROM period_person_total f WHERE f.sheet_id = t.sheet_id AND f.period_name = t.period_name AND f.person_id = ?)",
214	                fromId, sheetId, intoId, fromId);
215	        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND person_id = ? AND period_name IN"
216	                + " (SELECT period_name FROM period_person_total WHERE sheet_id = ? AND person_id = ?)", sheetId, fromId, sheetId, intoId);
217	        jdbc.update("UPDATE period_person_total SET person_id = ? WHERE sheet_id = ? AND person_id = ?", intoId, sheetId, fromId);
218	        // What is dropped with them.
219	        jdbc.update("DELETE FROM person_hold WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
220	        jdbc.update("DELETE FROM person_watch WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
221	        jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
222	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?", sheetId, fromId);
223	        jdbc.update("INSERT INTO person_merged SELECT p.*, (SELECT today FROM sheet WHERE id = ?) FROM person p WHERE p.sheet_id = ? AND p.id = ?",
224	                sheetId, sheetId, fromId);
225	        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, fromId);
226	    }
