244	            found = withGrades(sheetId, withAliases(sheetId, jdbc.query("SELECT * FROM person WHERE sheet_id = ? AND id IN"
245	                    + " (SELECT person_id FROM person_alias WHERE sheet_id = ? AND LOWER(TRIM(alias)) = LOWER(TRIM(?))) ORDER BY id",
246	                    ROW, sheetId, sheetId, name)));
247	        }
248	        return found.isEmpty() ? null : found.get(0);
249	    }
250	
251	    /** Whether another person on the sheet already has this name, or anyone on the sheet has it as an alias,
252	     *  compared without regard to case. */
253	    public boolean nameTaken(String sheetId, String name, Long exceptId) {
254	        Integer count = jdbc.queryForObject(
255	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND LOWER(TRIM(name)) = LOWER(TRIM(?))"
256	                        + (exceptId == null ? "" : " AND id <> " + exceptId.longValue()),
257	                Integer.class, sheetId, name);
258	        Integer aliases = jdbc.queryForObject(
259	                "SELECT COUNT(*) FROM person_alias WHERE sheet_id = ? AND LOWER(TRIM(alias)) = LOWER(TRIM(?))",
260	                Integer.class, sheetId, name);
261	        return (count != null && count > 0) || (aliases != null && aliases > 0);
262	    }
