264	    /** Whether another person on the sheet already has this contact. */
265	    public boolean contactTaken(String sheetId, String contact, Long exceptId) {
266	        Integer count = jdbc.queryForObject(
267	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ?"
268	                        + (exceptId == null ? "" : " AND id <> " + exceptId.longValue()),
269	                Integer.class, sheetId, contact);
270	        return count != null && count > 0;
271	    }
