278	    public Person add(String sheetId, String name, String grade, Integer terms, String contact) {
279	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
280	        jdbc.update(con -> {
281	            PreparedStatement ps = con.prepareStatement(
282	                    "INSERT INTO person (sheet_id, name, grade, terms, contact, added_on) VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
283	                    Statement.RETURN_GENERATED_KEYS);
284	            ps.setString(1, sheetId);
285	            ps.setString(2, name);
286	            ps.setString(3, grade);
287	            ps.setObject(4, terms, java.sql.Types.INTEGER);
288	            ps.setString(5, contact);
289	            ps.setString(6, sheetId);
290	            return ps;
291	        }, keys);
292	        Person person = new Person(keys.getKey().longValue(), sheetId, name, grade);
293	        person.setTerms(terms);
294	        person.setContact(contact);
295	        writeHistory(person);
296	        // The first grade a person is given applies from the beginning of time.
297	        person.recordGrade(Person.BEGINNING, grade);
298	        writeRecordedGrade(person);
299	        person.setToday(sheets.today(sheetId));
300	        return person;
301	    }
