304	     *  version is left as it is — a statement is not an edit. */
305	    public void saveStatement(Person person) {
306	        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE sheet_id = ? AND id = ?",
307	                person.getStatementCount(), person.getStatedTotal(),
308	                person.getStatementDate() == null ? null : java.sql.Date.valueOf(person.getStatementDate()),
309	                person.getSheetId(), person.getId());
