320	     *  before it (no due-total or date when there is none, or it is not known). The count goes down by one. */
321	    public void cancelStatement(Person person) {
322	        List<Long> last = jdbc.query("SELECT seq FROM person_statement WHERE sheet_id = ? AND person_id = ? AND NOT cancelled ORDER BY seq DESC LIMIT 1",
323	                (rs, i) -> rs.getLong(1), person.getSheetId(), person.getId());
324	        if (!last.isEmpty()) {
