329	        person.setStatedTotal(null);
330	        person.setStatementDate(null);
331	        jdbc.query("SELECT stated_total, statement_date FROM person_statement WHERE sheet_id = ? AND person_id = ? AND NOT cancelled ORDER BY seq DESC LIMIT 1",
332	                rs -> {
