            + " ON k.sheet_id = c.sheet_id AND k.person_id = c.person_id AND k.claim_number = c.corrects";

    /** The listed_seq after every claim's: a new or moved claim is listed first. */
    private static final String NEXT_LISTED = "(SELECT COALESCE(MAX(listed_seq), 0) + 1 FROM claim)";

    private final JdbcTemplate jdbc;

    private final Holidays holidays;

    public Claims(JdbcTemplate jdbc, Holidays holidays) {
        this.jdbc = jdbc;
        this.holidays = holidays;
    }

    /** Records the claim's figure-moving columns as they now stand in its history, dated the sheet's today. */
    private void history(String sheetId, long id) {
        jdbc.update("INSERT INTO claim_history (sheet_id, claim_id, set_on, person_id, amount, claim_date, status, settled_due,"
                + " stated, stated_due, due_by, deferred_until, corrects, claim_number, opened_by, note, proofs, split_from, late_entry, settle_batch)"
                + " SELECT c.sheet_id, c.id, s.today, c.person_id, c.amount, c.claim_date, c.status, c.settled_due, c.stated,"
                + " c.stated_due, c.due_by, c.deferred_until, c.corrects, c.claim_number, c.opened_by, c.note, c.proofs,"
                + " c.split_from, c.late_entry, c.settle_batch"
                + " FROM claim c JOIN sheet s ON s.id = c.sheet_id WHERE c.sheet_id = ? AND c.id = ?", sheetId, id);
    }

    /** The sheet's claims, newest first. */
    public List<Claim> list(String sheetId) {
        return withLogs(sheetId, jdbc.query(SELECT + " WHERE c.sheet_id = ? ORDER BY c.listed_seq DESC, c.id DESC", ROW, sheetId));
    }

    /** The claims with their status logs (see {@link ClaimLog}), oldest line first. */
    private List<Claim> withLogs(String sheetId, List<Claim> claims) {
        Map<Long, List<String>> logs = new HashMap<>();
        jdbc.query("SELECT claim_id, status, by_user, log_date, due FROM claim_log WHERE sheet_id = ? ORDER BY id", rs -> {
            logs.computeIfAbsent(rs.getLong("claim_id"), id -> new ArrayList<>())
                    .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
                            + rs.getDate("log_date").toLocalDate() + " due=" + rs.getString("due"));
        }, sheetId);
        claims.forEach(claim -> claim.setLog(logs.getOrDefault(claim.getId(), List.of())));
        Map<Long, List<ClaimComment>> comments = new HashMap<>();
        jdbc.query("SELECT claim_id, by_user, comment_date, text FROM claim_comment WHERE sheet_id = ? ORDER BY id", rs -> {
            comments.computeIfAbsent(rs.getLong("claim_id"), id -> new ArrayList<>()).add(new ClaimComment(
                    rs.getString("by_user"), rs.getDate("comment_date").toLocalDate(), rs.getString("text")));
        }, sheetId);
        claims.forEach(claim -> claim.setComments(comments.getOrDefault(claim.getId(), List.of())));
        return claims;
    }

    /** A person's claims on the sheet, newest first. */
    public List<Claim> ofPerson(String sheetId, long personId) {
        return jdbc.query(SELECT + " WHERE c.sheet_id = ? AND c.person_id = ? ORDER BY c.listed_seq DESC, c.id DESC", ROW, sheetId, personId);
    }

    public Claim find(String sheetId, long id) {
        List<Claim> found = jdbc.query(SELECT + " WHERE c.sheet_id = ? AND c.id = ?", ROW, sheetId, id);
        return found.isEmpty() ? null : found.get(0);
    }

    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, LocalDate dueBy) {
        return add(sheetId, personId, amount, date, note, null, dueBy);
    }

    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate dueBy) {
        return add(sheetId, personId, amount, date, note, corrects, dueBy, null);
    }

    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate dueBy, String ref) {
        return add(sheetId, personId, amount, date, note, corrects, dueBy, ref, null);
    }

    /** Adds a DRAFT claim with its due-by fixed as given (keeping the terms it was fixed with), its external reference
     *  and its tags (null for none). */
    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects,
            LocalDate dueBy, String ref, String tags) {
        int terms = holidays.termsTo(sheetId, date, dueBy);
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by, ref, tags, terms, listed_seq) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, "
                            + NEXT_LISTED + ")",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(date));
            ps.setString(5, note);
            ps.setString(6, corrects);
            ps.setDate(7, Date.valueOf(dueBy));
            ps.setString(8, ref);
            ps.setString(9, tags);
            ps.setInt(10, terms);
            return ps;
        }, keys);
        Claim claim = new Claim(keys.getKey().longValue(), sheetId, personId, amount, date, note, ClaimStatus.DRAFT, null, null, null);
        history(sheetId, claim.getId());
        claim.setCorrects(corrects);
        claim.setDueBy(dueBy);
        claim.setTerms(terms);
        claim.setRef(ref);
        claim.setTags(tags);
        recordTags(sheetId, tags);
        claim.setCorrectedDate(correctedDate(sheetId, personId, corrects));
        return claim;
    }

    /** Remembers each of the tags (comma separated; null for none) as used on the sheet. */
    private void recordTags(String sheetId, String tags) {
        if (tags == null) return;
        for (String tag : tags.split(",")) {
            jdbc.update("MERGE INTO sheet_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (?, ?)", sheetId, tag);
        }
    }

    /** Every tag ever used on the sheet's claims, sorted. */
    public List<String> tagsUsed(String sheetId) {
        return found != null && found > 0;
    }

    /** Moves the claim to its (new) person, listed as their newest claim, and leaves it unbound. */
    public void reassign(Claim claim) {
        jdbc.update("UPDATE claim SET person_id = ?, stated = ?, stated_due = ?, claim_number = ?, listed_seq = " + NEXT_LISTED
                + " WHERE sheet_id = ? AND id = ?", claim.getPersonId(), claim.isStated(), claim.getStatedDue(), claim.getNumber(),
                claim.getSheetId(), claim.getId());
        history(claim.getSheetId(), claim.getId());
    }

    /** Moves the claim to the person its person was merged into, listed as their newest claim, its number and date
     *  kept, and leaves it unbound from any statement. */
    public void merge(Claim claim, long intoId) {
        jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, listed_seq = " + NEXT_LISTED
                + " WHERE sheet_id = ? AND id = ?", intoId, claim.getSheetId(), claim.getId());
        history(claim.getSheetId(), claim.getId());
    }

    /** Keeps a comment on the claim, written by the user on the sheet's today. */
    public void comment(Claim claim, String user, String text) {
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * Gives an opening claim its number. While the sheet's period numbering from is set and the sheet's
 * today is on or after it, the number counts from 1 within the claim's period: {@code <period>-<n>},
 * or {@code X-<n>} in its own sequence for a claim in no period. Otherwise it is the sheet-wide number,
 * whose sequence only the claims numbered sheet-wide advance.
 */
@Repository
public class ClaimNumbering {

    /** The prefix of the sequence of claims whose due-by is in no period. */
    public static final String NO_PERIOD = "X";

    private final JdbcTemplate jdbc;

    private final Sheets sheets;

    private final Settings settings;

    private final Periods periods;

    public ClaimNumbering(JdbcTemplate jdbc, Sheets sheets, Settings settings, Periods periods) {
        this.jdbc = jdbc;
        this.sheets = sheets;
        this.settings = settings;
        this.periods = periods;
    }

    /** Whether claims are numbered within their period now: the period numbering from is set and the sheet's today is on or after it. */
    public boolean perPeriod(String sheetId) {
        LocalDate from = settings.periodNumberingFrom(sheetId);
        return from != null && !sheets.today(sheetId).isBefore(from);
    }

    /** The next number for a claim dated on the date, opened now. */
    public String next(String sheetId, LocalDate claimDate) {
        if (!perPeriod(sheetId)) {
            return String.valueOf(sheets.nextClaimNumber(sheetId));
        }
        String period = periods.nameOn(sheetId, claimDate);
        String key = period == null ? "" : period;
        // Lock the sheet's row so claims opened at the same moment get distinct numbers.
        jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", (rs, i) -> rs.getString(1), sheetId);
        jdbc.update("MERGE INTO period_claim_number (sheet_id, period_name, last_number) KEY (sheet_id, period_name)"
                + " VALUES (?, ?, COALESCE((SELECT last_number FROM period_claim_number WHERE sheet_id = ? AND period_name = ?), 0) + 1)",
                sheetId, key, sheetId, key);
        Long n = jdbc.queryForObject("SELECT last_number FROM period_claim_number WHERE sheet_id = ? AND period_name = ?",
                Long.class, sheetId, key);
        return (period == null ? NO_PERIOD : period) + "-" + n;
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimResponse;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them — each person's claimed and due-total, and the
 * sheet's claimed-total and due-total, each person's and the sheet's overdue-total (the dues of their overdue claims, uncapped), each person's due-total held to the sheet's cap — worked out on the server so a change can audit what it
 * moved: after the change's own lines, one ROLLUP line per person whose figures changed (people in
 * the order they were added; a new person counts as changed), then a TOTALS line when the sheet's
 * totals changed. The sheet's due-total and overdue-total leave out the single highest and the single
 * lowest person's figure when three or more people have one (n/a is no figure).
 */
@Service
public class Rollup {

    private static final String NA = "n/a";

    private final People people;
    private final Claims claims;
    private final Rates rates;
    private final Sheets sheets;
    private final Settings settings;
    private final Audit audit;

    public Rollup(People people, Claims claims, Rates rates, Sheets sheets, Settings settings, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's figures now. */
    public RollupFigures figures(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        LocalDate policyDate = settings.policyDate(sheetId);
        BigDecimal cap = settings.cap(sheetId);
        List<Claim> all = claims.list(sheetId);
        Map<Long, RollupFigures.PersonFigures> byPerson = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            boolean anyFigure = false;
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !person.countsLive(claim, today)) {
                    continue;
                }
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = due(claim, person, today, policyDate);
                if (figure != null) {
                    anyFigure = true;
                    due = due.add(figure);
                    if (isOverdue(claim, grace(claim, person), today)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            // n/a only when no claim keeps or gets a figure (each at the grade in force on its date).
            boolean na = !anyFigure && rates.find(sheetId, person.getGrade(), today) == null;
            due = Settings.capped(due, cap);
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dues.add(due);
            }
            overdues.add(overdue);
            byPerson.put(person.getId(), new RollupFigures.PersonFigures(person.getName(),
                    show(claimed), na ? NA : show(due), show(overdue)));
        }
        return new RollupFigures(byPerson, show(claimedTotal), show(trimmedSum(dues)), show(trimmedSum(overdues)));
    }

    /** A claim's due as the screen shows it now; null for n/a. */
    public BigDecimal due(Claim claim, Person person) {
        String sheetId = claim.getSheetId();
        return due(claim, person, sheets.today(sheetId), settings.policyDate(sheetId));
    }

    /** A claim's due: fixed when settled; else the figure a statement bound it to, or its amount at the rate of its person's grade
     *  in force on its date, with its late charge (each 30-day boundary at the late percent in force on it) as of today on top,
     *  raised to the floor in force on its date. */
    private BigDecimal due(Claim claim, Person person, LocalDate today, LocalDate policyDate) {
        String sheetId = claim.getSheetId();
        RoundingMode rounding = Rounding.of(claim, policyDate);
        BigDecimal fixed = ClaimResponse.fixedDue(claim);
        BigDecimal figure = fixed != null || claim.isBound() ? fixed
                : Rates.due(claim.getAmount(), rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate()), rounding);
        return LateCharge.due(claim, figure, settings.floor(sheetId, claim.getDate()), on -> settings.latePct(sheetId, on), today, rounding,
                grace(claim, person));
    }

    /** Audit (on commit) one SNAPSHOT line per person, in list order, with their due-total in {@code before}. */
    public void recordSnapshots(String sheetId, String user, RollupFigures before) {
        String prefix = " sheet=" + sheetId + " by=" + user;
        before.people().values().forEach(was -> audit.recordOnCommit("SNAPSHOT" + prefix
                + " name=" + was.name() + " due-total=" + was.dueTotal()));
    }

    /** Audit (on commit) the figures that moved since {@code before}, as taken by {@code user}. */
    public void recordChanges(String sheetId, String user, RollupFigures before) {
        RollupFigures after = figures(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, now) -> {
            RollupFigures.PersonFigures was = before.people().get(id);
            if (was == null || !Objects.equals(was.claimed(), now.claimed())
                    || !Objects.equals(was.dueTotal(), now.dueTotal())
                    || !Objects.equals(was.overdueTotal(), now.overdueTotal())) {
                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
                        + " claimed=" + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        });
        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
                || !before.overdueTotal().equals(after.overdueTotal())) {
            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
        }
    }

    /** The grace days of the claim's person's grade in force on its date, as in force on that date (0 for none). */
    private int grace(Claim claim, Person person) {
        return settings.grace(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
    }

    /** A claim is overdue when it is OPEN (or PENDING) and its due-by plus its grace days is before the sheet's today. */
    private static boolean isOverdue(Claim claim, int grace, LocalDate today) {
        return claim.getStatus().isOpen() && claim.getDueBy() != null && LateCharge.lateFrom(claim, grace).isBefore(today);
    }

    /** People's figures added up, leaving out the single highest and the single lowest when there are three or more. */
    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        if (figures.size() < 3) {
            return sum;
        }
        return sum.subtract(figures.stream().max(BigDecimal::compareTo).orElseThrow())
                .subtract(figures.stream().min(BigDecimal::compareTo).orElseThrow());
    }

    private static String show(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
